with p as (
  insert into public.products (category_id, destination_id, name, slug, description, featured, sort)
  select c.id, d.id, 'Cannes Perfume', 'cannes-perfume', 'Evening light on the Croisette — velvet petals, a glass of something golden and the hum of the festival after dark.', true, 0
  from public.categories c, public.destinations d
  where c.slug = 'perfume' and d.slug = 'cannes'
  returning id
), img as (
  insert into public.product_images (product_id, url, alt, sort)
  select p.id, '/images/destinations/cannes.jpg', 'Cannes — Red carpet evenings, crimson blooms and warm amber.', 0 from p
  union all
  select p.id, '/images/products/perfumes-trio.jpg', 'Solei perfume bottles', 1 from p
), v as (
  insert into public.product_variants (product_id, label, size_ml, sku, price_fils, low_stock_threshold)
  select p.id, '50 ml', 50, 'SOL-P-CAN-50', 28000, 5 from p
  returning id
)
insert into public.variant_costs (variant_id, cost_fils) select v.id, 9000 from v;

